// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Sosyoloji kuramları ve sosyologlar (kolay).
const ozSocialscience6Kolay = <(String, String, List<String>, String)>[
  ('Brezilya bayrağında yer alan "Düzen ve İlerleme" sözü hangi düşünürün öğretisinden alınmıştır?', 'Auguste Comte', ['Karl Marx', 'Herbert Spencer', 'Alexis de Tocqueville'], '"Ordem e Progresso" sözü, 19. yüzyıl sonunda Brezilya\'da cumhuriyeti kuran kadroları etkileyen Comte pozitivizminin "düzen ve ilerleme" ilkesinden gelir.'),
  ('Herbert Spencer\'a göre evrim, gerek doğada gerekse toplumda hangi yönde ilerleyen bir süreçtir?', 'Basit ve türdeş olandan karmaşık ve farklılaşmış olana', ['Karmaşık olandan basit ve türdeş olana', 'Belirli bir yönelim olmadan, tümüyle düzensiz ve rastlantısal biçimde', 'Döngüsel olarak başlangıç noktasına geri dönerek'], 'Spencer evrimi, türdeş (homojen) yapıların zamanla farklılaşıp türdeş olmayan (heterojen) ve bütünleşmiş yapılara dönüşmesi olarak tanımladı.'),
  ('Herbert Spencer\'ın görüşlerine dayanarak toplumda da yalnız güçlülerin ayakta kalması gerektiğini, yoksullara yardımın doğal ayıklanmayı bozduğunu savunan anlayışa ne ad verilir?', 'Sosyal Darwinizm', ['Sosyal demokrasi', 'Yapısal işlevselcilik', 'Sembolik etkileşimcilik'], 'Spencer\'ın evrim anlayışını topluma uygulayan sosyal Darwinizm, rekabeti ilerlemenin kaynağı sayar ve devletin yoksullara yardımına karşı çıkar.'),
  ('Spencer\'ın devlet müdahalesine ilişkin tutumu ile ekonomideki hangi anlayış örtüşür?', 'Bırakınız yapsınlar', ['Merkezî planlama', 'Korumacı merkantilizm', 'Kamu mülkiyetinin yaygınlaştırılması'], 'Spencer "Devlete Karşı İnsan" adlı eserinde devletin ekonomik ve toplumsal yaşama karışmasını eleştirdi. Bu tutum serbest piyasacı laissez-faire anlayışıyla örtüşür.'),
  ('Emile Durkheim\'ın toplumsal olguların nasıl gözlemlenip açıklanacağını sistemli biçimde ortaya koyduğu 1895 tarihli eseri hangisidir?', 'Sosyolojik Yöntemin Kuralları', ['Dinsel Yaşamın İlkel Biçimleri', 'Ahlak Eğitimi', 'Pragmatizm ve Sosyoloji'], 'Durkheim 1895\'te yayımlanan "Sosyolojik Yöntemin Kuralları"nda toplumsal olgunun tanımını, gözlem kurallarını ve normal ile patolojik olanın ayrımını ortaya koydu.'),
  ('Durkheim\'ın Avustralya yerlilerinin totemciliğinden yola çıkarak dinin toplumsal kökenini açıkladığı 1912 tarihli eseri hangisidir?', 'Dinsel Yaşamın İlkel Biçimleri', ['Protestan Ahlakı ve Kapitalizmin Ruhu', 'Totem ve Tabu', 'Altın Dal'], 'Durkheim\'ın son büyük eseri "Dinsel Yaşamın İlkel Biçimleri"dir. "Totem ve Tabu" Freud\'a, "Altın Dal" Frazer\'a aittir.'),
  ('Durkheim\'a göre bir toplumsal olgu, o toplum tipinde ve gelişim evresinde genel olarak görülüyorsa nasıl nitelendirilmelidir?', 'Normal', ['Patolojik', 'Anomik', 'Rastlantısal'], 'Durkheim, belli bir toplum tipinde ortalama ve yaygın görülen olguları normal; istisnai ve olağan dışı olanları patolojik saydı.'),
  ('Durkheim\'a göre bir ülkede büyük bir ulusal savaş sırasında intihar oranlarının düşmesinin nedeni hangisidir?', 'Ortak tehdit karşısında toplumsal bütünleşmenin artması', ['Savaşta ölümlerin istatistiklere girmemesi', 'Ekonomik refahın savaş döneminde yükselmesi', 'Kuralların gevşemesiyle bireylerin kendilerini daha özgür hissetmesi'], 'Durkheim siyasal bunalım ve savaş dönemlerinde ortak duyguların canlandığını, bireyin topluma daha sıkı bağlandığını ve egoist intiharların azaldığını gözlemledi.'),
  ('Durkheim\'a göre insanların tapındığı kutsal güç aslında neyin simgesel ifadesidir?', 'Toplumun kendisinin', ['Doğa olaylarının korkutuculuğunun', 'Bireysel rüyaların', 'Ekonomik sömürünün'], 'Durkheim, totem ve tanrıların topluluğun kendi gücünü ve birliğini simgelediğini, dinsel tapınmanın özünde topluma tapınma olduğunu savundu.'),
  ('Durkheim eğitimi nasıl tanımlar?', 'Yetişkin kuşağın genç kuşağı yöntemli biçimde toplumsallaştırması', ['Bireyin doğuştan getirdiği yetenekleri kendiliğinden ortaya çıkarması', 'Yalnızca mesleki beceri kazandırma süreci', 'Bireyi toplumdan bağımsız kılma çabası'], 'Durkheim\'a göre eğitim, toplumun varlığını sürdürmesi için gerekli fikir ve duyguları genç kuşağa aktaran yöntemli bir toplumsallaştırma sürecidir.'),
  ('Aşağıdakilerden hangisi Durkheim\'ın tanımladığı anlamda bir "toplumsal olgu"ya en uygun örnektir?', 'Bir ülkede kullanılan dil ve para birimi', ['Bir kişinin sabah uyanınca esnemesi', 'Bir bireyin kişisel renk tercihi', 'Bir kişinin anne ve babasından aldığı doğuştan göz rengi'], 'Dil ve para birimi bireyden önce vardır, bireyin dışındadır ve ona uymayı dayatır. Bu nedenle Durkheim\'ın toplumsal olgu tanımına uyar; diğerleri bireysel ya da biyolojiktir.'),
  ('Max Weber\'in "Siyaset Meslek Olarak" konferansında yaptığı ünlü devlet tanımında devleti diğer topluluklardan ayıran özellik hangisidir?', 'Belirli bir toprakta meşru fiziksel şiddet kullanma tekelini elinde tutması', ['Ortak bir dil ve dinin bulunması', 'Vergi toplamayan gönüllü bir birlik olması', 'Bütün yurttaşların yasama, yürütme ve yargı işlerine doğrudan ve eşit katılabilmesi'], 'Weber devleti amaçlarıyla değil, kendine özgü aracıyla tanımlar: belirli bir toprak üzerinde meşru fiziksel güç kullanma tekelini başarıyla elinde tutan insan topluluğu.'),
  ('Weber\'e göre bir siyasetçi, eylemlerinin öngörülebilir sonuçlarını hesaba katıp bunlardan kendini sorumlu tutuyorsa hangi etik anlayışa göre davranmaktadır?', 'Sorumluluk etiği', ['İnanç (kanaat) etiği', 'Erdem etiği', 'Ödev etiği'], 'Weber inanç etiği ile sorumluluk etiğini ayırır. İnanç etiğinde kişi sonuçlara bakmadan ilkesine göre davranır; sorumluluk etiğinde ise eyleminin sonuçlarını hesaba katar.'),
  ('Weber\'e göre kapitalizmin ruhunun doğuşunda Kalvinizmin hangi öğretisi kilit rol oynamıştır?', 'Kimin kurtulacağının Tanrı tarafından önceden belirlendiği kader öğretisi', ['Günahların para ödenerek bağışlanabileceği öğretisi', 'Dünyadan elini eteğini çekip manastırda ömür boyu ibadetle yaşama öğretisi', 'Faiz almanın kesinlikle yasak olduğu öğretisi'], 'Kader (predestinasyon) öğretisi inananda derin bir kurtuluş kaygısı yarattı. Disiplinli çalışma ve başarı, seçilmiş olmanın işareti olarak görülmeye başlandı.'),
  ('Gelirleri birbirine yakın olduğu halde biri köklü bir aileden gelen saygın bir hekim, diğeri yeni zengin olmuş bir tüccar olan iki kişinin farklı toplumsal saygınlığa sahip olması Weber\'in hangi kavramıyla açıklanır?', 'Statü grubu', ['Üretim ilişkisi', 'Toplumsal olgu', 'Kolektif tasavvur'], 'Weber\'e göre statü, ekonomik konumdan ayrı olarak onur, saygınlık ve yaşam tarzına dayanır. Bu nedenle aynı gelirdeki kişiler farklı statü gruplarında yer alabilir.'),
  ('Komünist Parti Manifestosu\'nun ünlü açılış cümlesine göre, bugüne kadarki bütün toplumların tarihi neyin tarihidir?', 'Sınıf mücadelelerinin', ['Büyük devlet adamlarının', 'Dinsel fikirlerin gelişiminin', 'Teknik buluşların'], 'Manifesto "Bugüne kadarki bütün toplumların tarihi sınıf mücadeleleri tarihidir" cümlesiyle başlar ve tarihi ezen-ezilen sınıflar arasındaki çatışmayla açıklar.'),
  ('Simmel\'e göre moda hangi iki karşıt eğilimin birlikte işlemesiyle sürer?', 'Taklit etme ve başkalarından ayrışma isteği', ['Üretim ve tüketim dengesi', 'Dinsel inanç ve bilimsel bilgi', 'Kır nüfusu ile kent nüfusu arasındaki denge'], 'Moda bir yandan bir gruba benzeme, öte yandan diğerlerinden ayrışma isteğini doyurur. Alt kesimler taklit ettikçe üst kesimler yeni bir modaya yönelir.'),
  ('Bir anonim şirketin hissedarlarının birbirlerini tanımadan yalnızca kâr payı beklentisiyle aynı ortaklıkta bulunması Tönnies\'in hangi kavramına örnektir?', 'Cemiyet', ['Cemaat', 'Asabiyet', 'Mekanik dayanışma'], 'Anonim şirket kişisel bağlara değil, çıkara ve sözleşmeye dayanır. Tönnies bu tür ilişkileri cemiyetin tipik örneği sayar.'),
  ('ABD\'de ilk sosyoloji bölümü 1892\'de hangi üniversitede kurulmuştur?', 'Chicago Üniversitesi', ['Harvard Üniversitesi', 'Columbia Üniversitesi', 'Yale Üniversitesi'], 'Chicago Üniversitesi\'nde Albion Small\'un başkanlığında kurulan bölüm, ABD\'deki ilk sosyoloji bölümüdür ve Chicago Okulu\'nun çekirdeğini oluşturur.'),
  ('Robert E. Park\'ın "marjinal insan" kavramı kimi anlatır?', 'İki farklı kültürün sınırında yaşayan ve ikisine de tam ait olamayan kişiyi', ['Toplumun en yoksul ve en dışlanmış kesiminde yaşayan, sürekli işsiz kalan kişiyi', 'Suç işlemeyi meslek haline getiren kişiyi', 'Kırsal kesimde yalnız yaşayan çiftçiyi'], 'Park, göçmenler ve kültürel melezler gibi iki kültür arasında kalan bireylerin hem bir gerilim yaşadığını hem de iki kültüre geniş bir bakış kazandığını belirtir.'),
  ('Burgess\'in eşmerkezli halkalar modelinde iş merkezinin hemen çevresinde yer alan, ucuz konutların, yeni göçmenlerin ve yüksek suç oranlarının görüldüğü bölgeye ne ad verilir?', 'Geçiş bölgesi', ['Banliyö bölgesi', 'İşçi konutları bölgesi', 'Varlıklı konut bölgesi'], 'Burgess\'e göre merkezi iş alanı genişledikçe çevresindeki eski konutlar değer kaybeder; bu geçiş bölgesi göçmenlerin ilk yerleştiği ve toplumsal çözülmenin en yoğun olduğu alandır.'),
  ('Mead\'in düşüncesinin dayandığı ve onu John Dewey ile birlikte temsil ettiği felsefi akım hangisidir?', 'Pragmatizm', ['Varoluşçuluk', 'Pozitivizm', 'Yapısalcılık'], 'Mead, Chicago\'da Dewey ile birlikte pragmatist felsefenin önde gelen temsilcisiydi. Düşüncenin eylem ve uyum sürecinde ortaya çıktığı fikri onun benlik kuramını da etkiledi.'),
  ('"Sembolik etkileşimcilik" terimini 1937\'de ilk kez kullanan ve Mead\'in görüşlerini sistemleştiren sosyolog kimdir?', 'Herbert Blumer', ['Erving Goffman', 'Harold Garfinkel', 'Talcott Parsons'], 'Blumer, hocası Mead\'in görüşlerini sistemli bir sosyolojik yaklaşıma dönüştürdü ve bu yaklaşıma sembolik etkileşimcilik adını verdi.'),
  ('Erving Goffman\'ın toplumsal yaşamı bir tiyatro sahnesine benzeterek bireylerin başkalarına kendilerini nasıl sunduğunu incelediği eseri hangisidir?', 'Gündelik Yaşamda Benliğin Sunumu', ['Zihin, Benlik ve Toplum', 'Yalnız Kalabalık', 'Toplumsal Gerçekliğin Yapısı ve Kurumları'], 'Goffman bu eserinde dramaturjik yaklaşımı geliştirdi; bireyleri izleyicilerine belirli bir izlenim vermeye çalışan oyunculara benzetti.'),
  ('Bir asansörde ya da otobüste yabancıların birbirlerini kısaca fark edip ardından gözlerini kaçırarak birbirlerinin alanına saygı göstermesi Goffman\'ın hangi kavramıyla açıklanır?', 'Sivil kayıtsızlık', ['Rol çatışması', 'Toplumsal kapanma', 'Toplumsal anomi'], 'Goffman\'a göre sivil kayıtsızlık, kalabalık kamusal alanlarda karşıdakini tehdit etmediğimizi gösteren ince bir etkileşim ritüelidir.'),
  ('Goffman\'ın dramaturjik yaklaşımında, bir restoranın garsonları ve aşçılarının müşterilere birlikte tutarlı bir izlenim vermek için işbirliği yapması hangi kavramla adlandırılır?', 'Ekip (takım) performansı', ['Kolektif bilinç', 'Gülen üçüncü', 'İstila ve ardıllık süreci'], 'Goffman\'a göre performanslar çoğu zaman bireysel değil, ortak bir izlenimi sürdürmek için birbirine bağımlı olan ekip üyelerince sergilenir.'),
  ('Parsons\'ın AGIL şemasına göre bir toplumda "amaca ulaşma" işlevini öncelikle hangi alt sistem karşılar?', 'Siyaset', ['Ekonomi', 'Aile ve eğitim', 'Hukuk ve toplumsal topluluk'], 'Parsons\'a göre ekonomi uyum, siyaset amaca ulaşma, hukuk ve toplumsal topluluk bütünleşme, aile-eğitim-din gibi kurumlar ise örüntünün sürdürülmesi işlevini üstlenir.'),
  ('Bir hekimin hastalarını tanıdık ya da yabancı olmalarına bakmadan, herkese aynı tıbbi ölçütlere göre davranması Parsons\'ın örüntü değişkenlerinden hangisine örnektir?', 'Evrenselcilik', ['Özelcilik', 'Yaygınlık', 'Duygusal yakınlık'], 'Parsons\'ın örüntü değişkenlerinde evrenselcilik, kişilere ilişkileri ne olursa olsun genel ölçütlerle davranmayı anlatır; özelcilik ise ilişkiye göre ayrıcalık tanımaktır. Modern meslek rolleri evrenselciliğe dayanır.'),
  ('Parsons\'ın "hasta rolü" kavramına göre hastanın toplumsal yükümlülüklerinden biri hangisidir?', 'İyileşmeye çalışmak ve uzman yardımı aramak', ['Hastalığından dolayı kendini suçlamak', 'Bütün olağan görevlerini aksatmadan sürdürmek', 'Tedaviyi reddedip dinlenmekle yetinmek'], 'Parsons\'a göre hasta olağan görevlerinden geçici olarak muaf tutulur ve hastalığından sorumlu sayılmaz; buna karşılık iyileşmeyi istemesi ve yetkin tıbbi yardım araması beklenir.'),
  ('Parsons ve Bales\'in aile içi rol ayrımına göre ailenin dış dünyayla ilişkisini ve geçimini sağlayan rolüne ne ad verilir?', 'Araçsal rol', ['Dışavurumcu rol', 'Duygusal rol', 'Bütünleştirici rol'], 'Parsons ve Bales araçsal rolü (geçim ve dış dünya) babaya, dışavurumcu rolü (duygusal destek) anneye yükledi. Bu ayrım sonradan feminist sosyologlarca yoğun biçimde eleştirildi.'),
  ('Coser\'in kavramlarına göre gerginliklerin, sistemi tehdit etmeden zararsız biçimde boşaltılmasını sağlayan şenlik, spor karşılaşması ya da mizah gibi kurumlara ne ad verilir?', 'Emniyet supabı kurumları', ['Total kurumlar', 'Ara mekanizmalar', 'Disiplin ve gözetim kurumları'], 'Coser\'e göre emniyet supabı kurumları, biriken düşmanlığı asıl kaynağına yöneltmeden dışa vurma olanağı sağlar; ancak sorunun kendisini çözmez.'),
  ('C. Wright Mills\'in "Güç Seçkinleri" adlı eserine göre ABD\'de önemli kararları birbirine bağlı üç seçkin grup verir. Bu gruplar hangileridir?', 'Askerî, ekonomik ve siyasal seçkinler', ['Dinî, akademik ve sanatçı seçkinler', 'Sendika, köylü ve esnaf önderleri', 'Basın, spor ve eğlence dünyası ünlüleri'], 'Mills büyük şirketlerin yöneticileri, ordunun üst kademeleri ve siyasal yönetim arasındaki iç içe geçmiş ilişkilerin bir güç seçkinleri katmanı oluşturduğunu savundu.'),
  ('C. Wright Mills\'in sosyolojik muhayyile kavramında "kişisel sorunlar" ile "kamusal meseleler" ayrımına en uygun örnek hangisidir?', 'Bir kişinin işsizliği kişisel sorun, yaygın kitlesel işsizlik kamusal meseledir', ['Bir kişinin hastalanması kamusal mesele, bir salgın kişisel sorundur', 'Her türlü işsizlik yalnızca kişisel bir başarısızlıktır', 'Kamusal meseleler yalnızca siyasetçileri ilgilendirir, sosyologların inceleme alanına girmez'], 'Mills\'e göre bireyin yaşadığı sıkıntıyı toplumsal yapı ve tarihle ilişkilendirmek sosyolojik muhayyilenin özüdür; yaygın işsizlik bireysel değil yapısal bir sorundur.'),
  ('C. Wright Mills\'in ABD\'de büyüyen büro çalışanları ve yöneticilerden oluşan yeni orta sınıfı incelediği 1951 tarihli eseri hangisidir?', 'Beyaz Yakalılar', ['Yalnız Kalabalık', 'Organizasyon İnsanı', 'Aylak Sınıfın Teorisi'], 'Mills "Beyaz Yakalılar"da büyük bürokratik örgütlerde çalışan yeni orta sınıfın siyasal kayıtsızlığını ve yabancılaşmasını inceledi.'),
  ('Howard Becker\'ın "Hariciler" (Outsiders) adlı eserinde kullandığı "ahlak girişimcileri" kavramı kimleri anlatır?', 'Belirli davranışları yasaklayan kuralların konulması için kampanya yürütenleri', ['Kuralları çiğneyerek büyük kazanç sağlayan ve yasaları hiçe sayan suç örgütlerini', 'Toplumdan tümüyle çekilen bağımlıları', 'Kurallara harfiyen uyan memurları'], 'Becker\'a göre sapma kurallarını kendiliğinden doğmaz; ahlak girişimcileri bir davranışı sorun olarak tanımlatıp yasaklar konulmasını sağlar. ABD\'deki içki yasağı kampanyası buna örnektir.'),
  ('Bir kişinin hapis yatmış olmasının, onun meslek, babalık ya da komşuluk gibi diğer bütün kimliklerinin önüne geçerek nasıl görüldüğünü belirlemesi sosyolojide hangi kavramla açıklanır?', 'Ana (baskın) statü', ['Verilmiş statü', 'Rol mesafesi', 'Statü tutarlılığı ilkesi'], 'Everett Hughes\'un geliştirdiği ana statü kavramı, bir kişinin diğer bütün özelliklerinin önüne geçen ve onu tanımlayan statüyü anlatır. Becker sapkın etiketinin bu şekilde işlediğini gösterdi.'),
  ('Travis Hirschi\'nin toplumsal bağ kuramı, diğer suç kuramlarından farklı olarak hangi soruyu merkeze alır?', 'İnsanlar neden suç işlemez?', ['İnsanlar suç işlemeyi kimden öğrenir?', 'Suç oranları neden kentlerde yüksektir?', 'Suçlular neden etiketlenir?'], 'Hirschi\'ye göre suç işleme eğilimi herkeste vardır; asıl açıklanması gereken insanların neden kurallara uyduğudur. Yanıt, bireyi topluma bağlayan bağların gücüdür.'),
  ('Sykes ve Matza\'nın "nötrleştirme teknikleri" arasında "Kimseye zararım dokunmadı, zaten sigortalıydı" diyen bir hırsızın kullandığı teknik hangisidir?', 'Zararın inkârı', ['Sorumluluğun inkârı', 'Kurbanın inkârı', 'Yüksek bağlılıklara başvurma'], 'Sykes ve Matza\'ya göre suçlular toplumun değerlerini tümden reddetmez; çeşitli gerekçelerle suçluluk duygusunu nötrleştirir. Zararın inkârı, verilen zararın önemsiz olduğunu ileri sürmektir.'),
  ('Edwin Sutherland\'ın 1939\'da kullandığı "beyaz yakalı suç" kavramı hangi suçları anlatır?', 'Saygın ve yüksek statülü kişilerin meslekleri sırasında işlediği suçları', ['Yalnızca hapishanede işlenen suçları', 'Gençlerin kent merkezlerindeki sokak çeteleri içinde işlediği suçları', 'Savaş sırasında askerlerin işlediği suçları'], 'Sutherland, suç araştırmalarının yalnızca alt sınıflara odaklanmasını eleştirdi; şirket yöneticilerinin dolandırıcılık ve rüşvet gibi suçlarını beyaz yakalı suç olarak adlandırdı.'),
  ('Wilson ve Kelling\'in 1982\'de ortaya attığı "kırık pencereler" görüşüne göre bir mahallede onarılmayan küçük düzensizlikler neye yol açar?', 'Denetimin zayıf olduğu izlenimiyle daha ağır suçların artmasına', ['Mahalle sakinlerinin dayanışmasının kendiliğinden güçlenmesine', 'Suç oranlarının hiçbir biçimde değişmemesine', 'Polisin mahalleden tümüyle çekilmesinin suçu azaltmasına'], 'Bu görüşe göre kırık camlar ve duvar yazıları gibi işaretler kimsenin ilgilenmediği mesajını verir; bu da daha ciddi suçları cesaretlendirir.'),
  ('Nazilerin iktidara gelmesinin ardından Frankfurt Okulu düşünürlerinin enstitüyü taşıdıkları ve sürgün yıllarını geçirdikleri ülke çoğunlukla hangisidir?', 'ABD', ['Sovyetler Birliği', 'Faşist İtalya', 'İmparatorluk Japonyası'], 'Enstitü önce Cenevre\'ye, ardından New York\'ta Columbia Üniversitesi\'ne bağlı olarak ABD\'ye taşındı. Savaştan sonra Horkheimer ve Adorno Frankfurt\'a döndü.'),
  ('Adorno ve Horkheimer\'ın "Aydınlanmanın Diyalektiği" adlı eserinde aklın doğayı ve insanı denetlemeye yönelik bir araca dönüşmesini anlatan kavram hangisidir?', 'Araçsal akıl', ['Pratik akıl', 'İletişimsel akıl', 'Saf akıl'], 'Adorno ve Horkheimer\'a göre insanı özgürleştirmeyi vaat eden Aydınlanma aklı, amaçları sorgulamadan yalnızca en verimli aracı hesaplayan araçsal akla dönüşmüş ve yeni bir tahakküm biçimi yaratmıştır.'),
  ('Herbert Marcuse\'nin "Tek Boyutlu İnsan" adlı eserinde ileri sanayi toplumuna yönelttiği temel eleştiri hangisidir?', 'Tüketim ve sahte ihtiyaçlarla eleştirel düşüncenin bastırılması', ['Toplumun aşırı yoksulluk ve kıtlık nedeniyle hızla çökmekte olması', 'Bireylerin fazla özgür olup kuralları tanımaması', 'Bilim ve tekniğin yeterince gelişmemiş olması'], 'Marcuse, refah ve tüketimin insanlara dayatılan sahte ihtiyaçlar yarattığını, böylece bireylerin düzeni sorgulama yeteneğini yitirip tek boyutlu hale geldiğini savundu.'),
  ('Habermas\'ın "Kamusal Alanın Yapısal Dönüşümü" adlı eserine göre 18. yüzyılda burjuva kamusal alanının oluştuğu mekânlar arasında hangisi yer alır?', 'Kahvehaneler ve edebî salonlar', ['Kraliyet sarayının taht odası', 'Fabrika üretim bantları', 'Manastırların ibadet salonları'], 'Habermas\'a göre İngiliz kahvehaneleri, Fransız salonları ve gazeteler özel bireylerin bir araya gelip kamusal konuları akıl yoluyla tartıştığı yeni bir alan yarattı.'),
  ('Gramsci\'nin en önemli düşüncelerini Mussolini rejimi döneminde cezaevinde kaleme aldığı eseri hangisidir?', 'Hapishane Defterleri', ['Tarih ve Sınıf Bilinci', 'Kapital', 'Devlet ve Devrim'], 'Gramsci 1926\'da tutuklandı; hegemonya, sivil toplum ve aydınlar üzerine düşüncelerini cezaevinde tuttuğu ve ölümünden sonra yayımlanan defterlerde geliştirdi.'),
  ('Louis Althusser\'in ayrımına göre okul, aile, medya ve din kurumları iktidarın sürdürülmesinde hangi tür aygıt olarak işler?', 'İdeolojik devlet aygıtları', ['Baskıcı devlet aygıtları', 'Üretim güçleri', 'Emniyet supabı işlevi gören kurumlar'], 'Althusser polis, ordu ve mahkemeleri zorla işleyen baskıcı aygıtlar; okul, aile, medya ve dini ise rıza üreterek işleyen ideolojik devlet aygıtları olarak ayırır. Ona göre çağdaş toplumda baskın olan ideolojik aygıt okuldur.'),
  ('Bourdieu\'nün, toplumsal yaşamın sanat, bilim, ekonomi ya da din gibi kendi kuralları ve mücadele konuları olan görece özerk alanlara bölünmesini anlatan kavramı hangisidir?', 'Alan', ['Habitus', 'Doxa', 'Aura'], 'Bourdieu\'ye göre her alan, oyuncuların belirli sermaye türleri için yarıştığı bir mücadele uzayıdır. Bir alanda değerli olan sermaye bir diğerinde aynı değeri taşımayabilir.'),
  ('Bourdieu\'nün, egemenliğin ezilenler tarafından bile doğal ve meşru kabul edilmesini sağlayan, açık zor kullanmadan işleyen tahakküm biçimine verdiği ad hangisidir?', 'Sembolik şiddet', ['Yapısal şiddet', 'Meşru fiziksel şiddet', 'Kolektif şiddet'], 'Sembolik şiddet, eşitsiz düzenin kategorilerinin içselleştirilmesiyle işler; örneğin öğrencinin başarısızlığını kendi yeteneksizliğine bağlaması okulun kayırdığı kültürü görünmez kılar.'),
  ('Bir köyde varlıklı olmasa da dürüstlüğü ve cömertliğiyle tanınan bir yaşlının sözünün herkesçe dinlenmesi Bourdieu\'nün hangi sermaye türüyle açıklanır?', 'Sembolik sermaye', ['Ekonomik sermaye', 'Nesneleşmiş kültürel sermaye', 'Finansal sermaye'], 'Bourdieu\'ye göre sembolik sermaye, başkalarınca tanınan ve meşru görülen saygınlık, onur ve itibardır; diğer sermaye türleri tanındığında sembolik sermayeye dönüşür.'),
  ('Foucault\'ya göre disiplin kurumlarının askerlik, okul ve fabrikada ürettiği, hem daha verimli hem de daha itaatkâr kılınan bedenlere ne ad verilir?', 'Uysal bedenler', ['Kolektif bedenler', 'Kutsal bedenler', 'Özgür bedenler'], 'Foucault\'ya göre disiplin, bedeni parçalara ayırıp eğiterek onun yeteneklerini artırırken aynı zamanda boyun eğmesini sağlar; böylece uysal bedenler ortaya çıkar.'),
  ('Foucault\'nun nüfusun doğum, ölüm, sağlık ve yaşam süresi gibi süreçlerini yönetmeye yönelik modern iktidar biçimine verdiği ad hangisidir?', 'Biyoiktidar', ['Egemenlik iktidarı', 'Karizmatik otorite', 'Pastoral iktidar'], 'Foucault "Cinselliğin Tarihi"nin ilk cildinde öldürme hakkına dayanan eski egemenlik iktidarının yerini, yaşamı yönetmeye ve düzenlemeye çalışan biyoiktidarın aldığını savundu.'),
  ('Giddens\'a göre bir yolcunun uçak mühendisliği hakkında hiçbir bilgisi olmadan uçağa binmesi neyi gösterir?', 'Modern bireyin uzman sistemlerine duyduğu güvene dayanmasını', ['Geleneksel otoriteye bağlılığın sürdüğünü', 'Bireyin her konuda uzman olduğunu', 'Toplumsal ilişkilerin ve güvenin yalnızca yüz yüze tanışıklıkla kurulabildiğini'], 'Giddens, modern yaşamda teknik bilgisini kendimizin denetleyemediği uzman sistemlerine sürekli güvenmek zorunda olduğumuzu vurgular.'),
  ('Giddens\'ın 1990\'larda sol ile sağ arasında bir orta yol olarak önerdiği ve Tony Blair hükümetini etkileyen siyasal yaklaşım hangisidir?', 'Üçüncü Yol', ['Yeni Sağ', 'Sosyal Darwinizm', 'Bırakınız yapsınlar liberalizmi'], 'Giddens\'ın "Üçüncü Yol" kitabı, devletçi sosyal demokrasi ile serbest piyasacı neoliberalizm arasında yeni bir sosyal demokrasi önerdi.'),
  ('Ulrich Beck\'in "Risk Toplumu" adlı eserinde dile getirdiği "Yoksulluk hiyerarşiktir, duman demokratiktir" sözü neyi anlatır?', 'Modern risklerin sınıf ayrımı gözetmeden herkesi etkileyebildiğini', ['Yoksulluğun tümüyle ortadan kalktığını', 'Hava kirliliğinin ve çevre sorunlarının yalnızca yoksul semtlerde görüldüğünü', 'Demokrasinin çevre sorunlarını kendiliğinden çözdüğünü'], 'Beck\'e göre servetin dağılımı hiyerarşik olsa da nükleer kaza ya da hava kirliliği gibi riskler sınıf sınırlarını aşar; zenginler de bunlardan tam olarak korunamaz.'),
  ('Ulrich Beck\'in "Risk Toplumu" kitabının yayımlandığı 1986 yılında yaşanan ve kitabın tezlerini çarpıcı biçimde doğrular nitelikte görülen olay hangisidir?', 'Çernobil nükleer kazası', ['Berlin Duvarı\'nın yıkılması', 'Bhopal gaz faciası', 'Fukuşima nükleer kazası'], 'Kitap Çernobil kazasıyla aynı yıl yayımlandı. Sınır tanımayan radyoaktif bulut, Beck\'in modernliğin kendi ürettiği küresel risklerle yüz yüze olduğu savının sembolü oldu.'),
  ('Jean Baudrillard\'ın gerçek ile onun temsili arasındaki ayrımın ortadan kalktığı, göstergelerin gerçekten daha gerçek göründüğü durumu anlatan kavramı hangisidir?', 'Hipergerçeklik', ['Yabancılaşma', 'Şeyleşme', 'Kültürel gecikme'], 'Baudrillard\'a göre medya ve tüketim kültüründe simülasyonlar gerçeğin yerini alır; Disneyland gibi mekânlar bu hipergerçekliğin örnekleridir.'),
  ('Jean-François Lyotard\'ın "Postmodern Durum" (1979) adlı eserinde postmoderni tanımlarken kullandığı ifade hangisidir?', 'Büyük anlatılara karşı kuşkuculuk', ['Tarihin sona ermesi', 'Kitle toplumunun yükselişi', 'Ulus devletin güçlenip yeniden merkezîleşmesi'], 'Lyotard, ilerleme, özgürleşme ya da tarihin bir amaca doğru ilerlediği gibi bütün toplumu açıklayan büyük anlatıların inandırıcılığını yitirdiğini savundu.'),
  ('Ritzer\'e göre McDonaldlaşmanın boyutlarından biri olan "öngörülebilirlik"e en uygun örnek hangisidir?', 'Bir hamburgerin dünyanın her yerinde aynı tadı ve görünümü taşıması', ['Siparişin olabildiğince kısa sürede hazırlanması', 'Çalışanların yerine makinelerin kullanılması', 'Menüdeki ürünlerin boyutlarının ve fiyatlarının öne çıkarılması'], 'Ritzer McDonaldlaşmanın dört boyutunu verimlilik, hesaplanabilirlik, öngörülebilirlik ve denetim olarak sıralar. Her yerde aynı ürünle karşılaşmak öngörülebilirliktir.'),
  ('Ritzer\'in "rasyonelliğin irrasyonelliği" ifadesi neyi anlatır?', 'Verimlilik için kurulan sistemlerin insanlıktan uzaklaştıran sonuçlar doğurması', ['Rasyonel sistemlerin her koşulda kusursuz işleyip hiçbir yan etki doğurmaması', 'İnsanların akıl yürütme yeteneğini yitirmesi', 'Bilimsel yöntemin toplumsal olaylara uygulanamaması'], 'Ritzer, Weber\'in demir kafes düşüncesini izleyerek aşırı rasyonelleşmenin verimsizlik, tek düzelik ve insanlıktan çıkarma gibi beklenmedik sonuçlar ürettiğini vurgular.'),
  ('Chicago\'da 1889\'da Hull House adlı yerleşim evini kuran, göçmen mahallelerindeki toplumsal sorunlar üzerine çalışan ve 1931\'de Nobel Barış Ödülü alan sosyal reformcu kimdir?', 'Jane Addams', ['Harriet Martineau', 'Beatrice Webb', 'Charlotte Perkins Gilman'], 'Jane Addams, Hull House\'u yoksul göçmenlere hizmet veren bir merkez ve toplumsal araştırma alanı haline getirdi. Nobel Barış Ödülü\'nü alan ilk Amerikalı kadındır.'),
  ('Arlie Hochschild\'ın "İkinci Vardiya" adlı eserinde kullandığı bu kavram neyi anlatır?', 'Ücretli çalışan kadınların eve dönünce ev ve bakım işini de üstlenmesini', ['Fabrikalarda gece vardiyasında uzun süre çalışmanın işçilerin sağlığına etkisini', 'İki ayrı ücretli işte birden çalışmayı', 'Emeklilikten sonra yeniden işe dönmeyi'], 'Hochschild, çift kazançlı ailelerde kadınların işten sonra ev işleri ve çocuk bakımı için adeta ikinci bir vardiyaya başladığını gösterdi.'),
  ('Hukukçu Kimberlé Crenshaw\'ın 1989\'da ortaya attığı ve ırk, toplumsal cinsiyet ve sınıf gibi ayrımcılık eksenlerinin birbirinden bağımsız değil iç içe işlediğini anlatan kavram hangisidir?', 'Kesişimsellik', ['Çifte bilinç', 'Sembolik şiddet', 'Toplumsal kapanma'], 'Crenshaw, siyah kadınların yaşadığı ayrımcılığın ne yalnızca ırk ne de yalnızca cinsiyet temelli açıklanabildiğini; bu eksenlerin kesiştiği noktada özgün bir deneyim oluştuğunu gösterdi.'),
  ('Du Bois\'nın "Siyah Halkın Ruhu" adlı eserinde tanımladığı "çifte bilinç" kavramı neyi anlatır?', 'Kişinin kendine sürekli onu küçümseyen beyaz toplumun gözüyle bakması', ['Aynı anda iki dil konuşabilme yeteneğini', 'Bir kişinin iki farklı mesleği aynı anda ve aynı başarıyla birlikte yürütebilmesini', 'İki dine birden inanmayı'], 'Du Bois, Afrikalı Amerikalıların hem Amerikalı hem siyah olarak bölünmüş bir kimlik deneyimi yaşadığını ve kendilerini başkalarının küçümseyen bakışıyla ölçmek zorunda kaldığını anlattı.'),
  ('Du Bois\'nın "Yirminci yüzyılın sorunu ... sorunudur" diyerek dikkat çektiği sorun hangisidir?', 'Renk çizgisi', ['Sınıf çatışması', 'Nüfus patlaması', 'Kentsel yoksulluk'], 'Du Bois "Siyah Halkın Ruhu"nda yirminci yüzyılın temel sorununun ırklar arasındaki ayrımı simgeleyen renk çizgisi olacağını öngördü.'),
  ('David Riesman\'ın "Yalnız Kalabalık" adlı eserinde, davranışlarını aile ya da gelenekten çok akranlarının ve kitle iletişiminin beklentilerine göre ayarlayan modern Amerikalı insan tipine verdiği ad hangisidir?', 'Öteki-yönelimli', ['Gelenek-yönelimli', 'İç-yönelimli', 'Amaç-yönelimli'], 'Riesman toplumsal karakteri gelenek-yönelimli, iç-yönelimli ve öteki-yönelimli olarak üçe ayırdı; orta sınıf Amerikalıların giderek öteki-yönelimli hale geldiğini savundu.'),
  ('Karl Mannheim\'ın "İdeoloji ve Ütopya" adlı eserindeki ayrıma göre "ütopya" hangi düşünce türünü anlatır?', 'Var olan düzeni aşmaya ve dönüştürmeye yönelen düşünceleri', ['Var olan düzeni koruyup meşrulaştıran düşünceleri', 'Bilimsel olarak kanıtlanmış yasaları', 'Yalnızca bireysel ve kişisel hayalleri'], 'Mannheim\'a göre ideolojiler egemen grupların mevcut düzeni koruyan düşünceleri, ütopyalar ise alt grupların düzeni değiştirmeye yönelen düşünceleridir.'),
  ('Robert Putnam\'ın ayrımına göre farklı etnik, dinsel ya da toplumsal geçmişlerden gelen insanları birbirine bağlayan ağlar hangi sosyal sermaye türüne girer?', 'Köprü kuran sosyal sermaye', ['Bağlayıcı (içe dönük) sosyal sermaye', 'Kurumsallaşmış kültürel sermaye', 'Sembolik sermaye ve itibar'], 'Putnam benzer insanlar arasındaki sıkı bağları bağlayıcı, farklı gruplar arasında kurulan bağları ise köprü kuran sosyal sermaye olarak ayırır. Köprü kuran bağlar toplumsal bütünleşmeye daha çok katkı yapar.'),
  ('Ray Oldenburg\'un ev ve işyeri dışında insanların gayriresmî biçimde bir araya gelip sohbet ettiği kahvehane, berber ve kitapçı gibi mekânlar için kullandığı kavram hangisidir?', 'Üçüncü mekân', ['Total kurum', 'Kamusal alan', 'Geçiş bölgesi'], 'Oldenburg\'a göre ev birinci, işyeri ikinci mekândır; topluluk bağlarını güçlendiren gayriresmî buluşma yerleri ise üçüncü mekânlardır.'),
  ('Bir sosyolog, düğün törenlerinin akrabalık bağlarını tazeleyip yeni çiftin topluluğa katılmasını sağlayarak toplumsal düzene katkı yaptığını vurguluyor. Bu açıklama hangi yaklaşıma uygundur?', 'Yapısal işlevselcilik', ['Çatışma kuramı', 'Etnometodoloji', 'Postmodern toplum kuramı'], 'Bir uygulamanın toplumun bütünlüğüne ve sürekliliğine yaptığı katkıyı öne çıkarmak, işlevselci açıklamanın tipik biçimidir.'),
  ('Bir sosyolog, büyük spor kulüplerinin taraftar coşkusunu yayın gelirine dönüştürdüğünü ve bu gelirden en çok kulüp sahipleri ile reklam şirketlerinin yararlandığını ileri sürüyor. Bu bakış hangi kuramsal yaklaşıma yakındır?', 'Çatışma kuramı', ['Yapısal işlevselcilik', 'Sembolik etkileşimcilik', 'Fenomenolojik sosyoloji'], 'Bir kurumun kimin çıkarına işlediğini ve kaynakların eşitsiz dağılımını sorgulamak çatışma kuramının temel sorusudur.'),
  ('Bir araştırmacı, iki arkadaşın mesajlaşırken kullandığı emojilerin ilişkilerinin samimiyetine göre nasıl farklı anlamlar kazandığını inceliyor. Bu çalışma en çok hangi yaklaşımın ilgi alanına girer?', 'Sembolik etkileşimcilik', ['Dünya sistemleri kuramı', 'Yapısal işlevselcilik kuramı', 'Tarihsel materyalizm'], 'Simgelerin etkileşim içinde nasıl anlam kazandığını mikro düzeyde incelemek sembolik etkileşimciliğin konusudur.'),
  ('Bir sosyolog, çiftlerin evlilik kararını her iki tarafın da beklediği kazanç ve kayıpları karşılaştırarak verdiğini ileri sürüyor. Bu açıklama hangi yaklaşıma en yakındır?', 'Değişim ve rasyonel seçim yaklaşımı', ['Kültürel çalışmalar ve göstergebilim yaklaşımı', 'Yapısal işlevselcilik', 'Fenomenolojik sosyoloji'], 'Toplumsal ilişkileri tarafların ödül ve maliyet hesabına dayanan karşılıklı alışverişler olarak görmek, değişim ve rasyonel seçim kuramlarının temel varsayımıdır.'),
  ('Bir araştırmacı, insanların bir asansöre bindiklerinde neden kapıya dönük durduklarını ve bu sessiz kuralın bozulması durumunda nasıl tepki verdiklerini inceliyor. Bu araştırma en çok hangi yaklaşıma uygundur?', 'Etnometodoloji', ['Dünya sistemleri kuramı', 'Çatışma kuramı', 'Tarihsel karşılaştırmalı sosyoloji'], 'Gündelik düzeni sürdüren örtük kuralları ve bunların bozulmasına verilen tepkileri incelemek, Garfinkel\'in etnometodolojisinin konusudur.'),
  ('Bir sosyolog, ev işleri ve çocuk bakımının çoğunlukla ücretsiz olarak kadınlarca yapılmasının ekonominin işleyişini nasıl desteklediğini ve bu emeğin neden görünmez kaldığını sorguluyor. Bu bakış hangi kuramsal yaklaşıma aittir?', 'Feminist kuram', ['Yapısal işlevselcilik', 'Etnometodoloji', 'Değişim kuramı'], 'Toplumsal cinsiyete dayalı iş bölümünü ve kadın emeğinin görünmezliğini merkeze almak feminist kuramın ayırıcı özelliğidir.'),
  ('Bir sosyolog, reklamlarda gösterilen yaşam tarzlarının gerçek ürünlerden daha belirleyici hale geldiğini ve insanların metalardan çok onların imgelerini tükettiğini savunuyor. Bu yaklaşım en çok hangi düşünürün görüşlerini çağrıştırır?', 'Jean Baudrillard', ['Auguste Comte', 'Herbert Spencer', 'Emile Durkheim ve Marcel Mauss'], 'Tüketimin göstergeler ve imgeler üzerinden işlediği, simgelerin gerçekliğin önüne geçtiği düşüncesi Baudrillard\'ın postmodern toplum çözümlemesinin özüdür.'),
  ('Aşağıdaki sosyolog-yaklaşım eşleştirmelerinden hangisi doğrudur?', 'Herbert Blumer - sembolik etkileşimcilik', ['Talcott Parsons - çatışma kuramı', 'Ralf Dahrendorf - yapısal işlevselcilik', 'Harold Garfinkel - dünya sistemleri kuramı'], 'Blumer sembolik etkileşimciliğin adını koyan sosyologdur. Parsons işlevselciliğin, Dahrendorf çatışma kuramının, Garfinkel ise etnometodolojinin temsilcisidir.'),
  ('Aşağıdaki sosyologlardan hangisi mikro düzeyde gündelik etkileşimleri incelemesiyle tanınır?', 'Erving Goffman', ['Immanuel Wallerstein', 'Talcott Parsons', 'Karl Marx'], 'Goffman yüz yüze etkileşimlerin düzenini inceledi. Wallerstein küresel sistemi, Parsons toplumsal sistemi, Marx ise üretim tarzlarını makro düzeyde çözümledi.'),
  ('Yapısal işlevselcilik ile çatışma kuramı karşılaştırıldığında, toplumsal düzenin kaynağına ilişkin temel farkları hangisidir?', 'İşlevselcilik değerlerde uzlaşmayı, çatışma kuramı egemenliği öne çıkarır', ['İkisi de düzenin kaynağını yalnızca dinde görür', 'İşlevselcilik zor kullanımını, çatışma kuramı ise ortak değerlerde uzlaşmayı öne çıkarır', 'İkisi de toplumsal düzenin var olmadığını savunur'], 'İşlevselcilere göre düzen paylaşılan değerlerin içselleştirilmesinden doğar; çatışma kuramcılarına göre ise düzen, güçlü grupların egemenliği ve zayıfların boyun eğmesiyle sürer.'),
  ('Bir okulda öğrencilerin başarısını inceleyen üç sosyologdan biri okulun yetenekleri seçip uygun mesleklere dağıttığını, ikincisi okulun sınıf ayrımlarını yeniden ürettiğini, üçüncüsü öğretmenin öğrenciye taktığı etiketlerin başarıyı etkilediğini söylüyor. Bu açıklamalar sırasıyla hangi yaklaşımlara aittir?', 'İşlevselcilik, çatışma kuramı, sembolik etkileşimcilik', ['Çatışma kuramı, işlevselcilik, etnometodoloji', 'Sembolik etkileşimcilik, işlevselcilik, çatışma kuramı', 'İşlevselcilik, sembolik etkileşimcilik ve çatışma kuramı'], 'Seçme-dağıtma işlevi işlevselci, eşitsizliğin yeniden üretimi çatışma kuramcı, etiketlemenin etkisi ise sembolik etkileşimci bir açıklamadır.'),
  ('Bir sosyolog, yeni açılan bir alışveriş merkezinin mahalle ekonomisine canlılık getirdiğini ama küçük esnafın kapanmasıyla mahallenin yüz yüze ilişkilerini zayıflattığını belirtiyor. Bu değerlendirme Merton\'un hangi kavram çiftini uygulamaktadır?', 'İşlev ve işlev bozukluğu', ['Mekanik ve organik dayanışma', 'Altyapı ve üstyapı', 'Ön sahne ve kulis'], 'Merton\'a göre aynı yapı bazı kesimler ya da yönler için işlevsel, başkaları için işlev bozucu sonuçlar doğurabilir; sosyolog her ikisini de hesaba katmalıdır.'),
  ('Bir sosyolog, toplumların tarih boyunca hep aynı yönde, basitten karmaşığa doğru ilerlediği düşüncesine karşı çıkıyor ve her toplumun kendine özgü tarihsel yolunu vurguluyor. Bu sosyolog hangi klasik görüşü eleştirmektedir?', 'Tek çizgili evrimcilik', ['Sembolik etkileşimcilik', 'Etnometodoloji', 'Fenomenoloji'], 'Comte ve Spencer gibi klasik düşünürlerin tek çizgili evrimci şemaları, bütün toplumların aynı aşamalardan geçeceğini varsaydığı için eleştirilmiştir.'),
  ('Bir sosyolog, "Toplumu anlamak için önce insanların kendi dünyalarını nasıl anlamlandırdığını, onların gözünden bakarak kavramalıyız" diyor. Bu görüş aşağıdaki sosyologlardan hangisinin yöntem anlayışıyla en çok örtüşür?', 'Max Weber', ['Auguste Comte', 'Herbert Spencer', 'Immanuel Wallerstein'], 'Eylemcinin öznel anlamını yorumlayarak kavramayı (Verstehen) sosyolojinin temeline koyan Weber\'dir. Comte ve Spencer doğa bilimleri modelini, Wallerstein ise makro yapıları öne çıkarır.'),
  ('Bir sosyolog bir kasabadaki toplumsal değişmeyi incelerken önce kasabanın tarihini, sonra ekonomik yapısını, aile ilişkilerini ve dinsel yaşamını bir bütün olarak betimliyor. Bu araştırma tarzı hangi geleneği yansıtır?', 'Topluluk (monografik) çalışmaları geleneği', ['Laboratuvar deneyleri geleneği', 'Matematiksel modelleme geleneği', 'Yalnızca çevrimiçi anket ve telefon görüşmesi geleneği'], 'Le Play\'den Lynd çiftinin Middletown\'una, Kıray\'ın Ereğli\'sine uzanan topluluk çalışmaları, bir yerleşimi bütün kurumlarıyla birlikte ayrıntılı biçimde inceler.'),
  ('"Türk milletindenim, İslam ümmetindenim, Garp medeniyetindenim" sözü hangi düşünürün sentezci görüşünü özetler?', 'Ziya Gökalp', ['Prens Sabahattin', 'Namık Kemal', 'Yusuf Akçura'], 'Gökalp bu sözle millî kültür (hars), din ve Batı medeniyetinin tekniğini bir araya getiren sentezini dile getirdi.'),
  ('Durkheim\'ın "Toplum bireylerin basit toplamı değildir" yargısı, toplumun nasıl bir gerçeklik olduğu konusunda hangi görüşü dile getirir?', 'Bireylerin birleşmesinden kendine özgü yeni bir gerçeklik doğduğunu', ['Toplumun yalnızca onu oluşturan bireylerin aritmetik toplamından ibaret bir bütün olduğunu', 'Toplumun hiçbir zaman gerçek olmadığını', 'Toplumun biyolojik bir organizmadan farksız olduğunu'], 'Durkheim\'a göre bireylerin bir araya gelmesiyle, tıpkı kimyasal bileşiklerde olduğu gibi, parçalarda bulunmayan özelliklere sahip kendine özgü (sui generis) bir gerçeklik ortaya çıkar.'),
  ('C. Wright Mills\'e göre sosyolojik muhayyile, aşağıdaki ikisinin birlikte kavranmasını gerektirir. Bunlar hangileridir?', 'Kişisel yaşam öyküsü ve toplumun tarihi', ['Doğa yasaları ve matematik', 'Bireysel zekâ ve kalıtım', 'Dinsel metinler, gelenekler ve atasözleri'], 'Mills, ne bir bireyin yaşamının ne de bir toplumun tarihinin ikisi birlikte anlaşılmadan anlaşılabileceğini; sosyolojik muhayyilenin biyografi ile tarihi ilişkilendirme yetisi olduğunu söyler.'),
  ('Aşağıdaki eserlerden hangisi diğerlerinden önce yayımlanmıştır?', 'Komünist Parti Manifestosu', ['Durkheim\'ın İntihar\'ı', 'Weber\'in Protestan Ahlakı ve Kapitalizmin Ruhu', 'Riesman\'ın Yalnız Kalabalık\'ı'], 'Manifesto 1848\'de, İntihar 1897\'de, Protestan Ahlakı 1904-1905\'te, Yalnız Kalabalık ise 1950\'de yayımlandı.'),
  ('Aşağıdaki sosyologlardan hangisi diğerlerinden daha sonraki bir kuşağa aittir?', 'Anthony Giddens', ['Emile David Durkheim', 'Max Weber', 'Georg Simmel'], 'Durkheim (1858), Weber (1864) ve Simmel (1858) klasik kuşaktandır. Giddens 1938\'de doğmuştur ve çağdaş sosyologlar arasında yer alır.'),
  ('Aşağıdaki eserlerden hangisi Durkheim\'a ait değildir?', 'Toplumsal Eylemin Yapısı', ['Toplumsal İşbölümü Üzerine', 'Sosyolojik Yöntemin Kuralları', 'Dinsel Yaşamın İlkel Biçimleri'], '"Toplumsal Eylemin Yapısı" Talcott Parsons\'ın 1937 tarihli eseridir. Diğer üçü Durkheim\'ın başlıca eserleridir.'),
  ('Aşağıdaki eserlerden hangisi Max Weber\'e ait değildir?', 'Paranın Felsefesi', ['Ekonomi ve Toplum', 'Hindistan\'ın Dini', 'Siyaset Meslek Olarak'], '"Paranın Felsefesi" Georg Simmel\'in 1900 tarihli eseridir. Diğerleri Weber\'in eserleridir.'),
  ('Aşağıdaki eserlerden hangisi Pierre Bourdieu\'ye ait değildir?', 'Gündelik Yaşamda Benliğin Sunumu', ['Ayrım', 'Yeniden Üretim', 'Pratik Bir Kuramın Taslağı ve Ötesi'], '"Gündelik Yaşamda Benliğin Sunumu" Erving Goffman\'ın eseridir. Diğer üçü Bourdieu\'nün çalışmalarıdır.'),
  ('İbn Haldun\'a göre bedevi yaşam ile hadari (kentli) yaşam arasındaki tarihsel ilişki nasıldır?', 'Bedevilik hadariliğin kaynağıdır; kentli yaşam ondan doğar', ['Hadarilik bedeviliğin kaynağıdır; kentliler zamanla kentleri terk edip göçebeleşir', 'İkisi birbirinden bağımsız olup hiç etkileşmez', 'Bedevilik yalnızca kentlerin yıkılmasıyla ortaya çıkar'], 'İbn Haldun bedevi yaşamın daha önce geldiğini ve kentlerin bedevilerin yerleşmesiyle kurulduğunu; bedevilerin amacının sonunda refah içindeki kentli yaşama ulaşmak olduğunu belirtir.'),
  ('Ziya Gökalp\'in asıl adı nedir?', 'Mehmed Ziya', ['Mehmed Emin Bey', 'Ahmed Ziya', 'Ali Rıza'], 'Diyarbakır\'da doğan düşünürün asıl adı Mehmed Ziya\'dır; Gökalp takma adını yazılarında kullanmış ve bu adla tanınmıştır.'),
  ('Ziya Gökalp\'in toplumsal düşüncesinde "halka doğru" ilkesi aydınlara hangi görevi yükler?', 'Halkın kültürünü öğrenip halka medeniyeti götürmek', ['Halktan tümüyle uzaklaşıp yalnızca Batı\'yı örnek almak', 'Halkın kültürünü tümüyle yok edip yerine yabancı bir kültürü yukarıdan yerleştirmek', 'Yalnızca saray çevresiyle ilişki kurmak'], 'Gökalp\'e göre aydınlar halka gidip onun harsını öğrenmeli, buna karşılık halka modern medeniyetin bilgisini götürmelidir; böylece seçkinlerle halk arasındaki kopukluk giderilir.'),
  ('Barrington Moore\'un "Diktatörlüğün ve Demokrasinin Toplumsal Kökenleri" adlı eserinde parlamenter demokrasiye giden yolda öne çıkardığı ünlü yargı hangisidir?', 'Burjuvazi yoksa demokrasi de olmaz', ['Köylü yoksa devlet de olmaz', 'Din yoksa toplum da olmaz', 'Ordu yoksa ulus ve vatan da olmaz'], 'Moore, İngiltere, Fransa ve ABD\'de güçlü bir ticari ve kentli burjuvazinin toprak aristokrasisinin gücünü kırmasının demokrasinin yolunu açtığını savundu.'),
  ('Bryan Wilson\'ın sekülerleşme tanımına en uygun ifade hangisidir?', 'Dinî düşünce ve kurumların toplumsal önemini yitirmesi süreci', ['Dinî kurumların sayısının hızla artması', 'Devletin bir dini resmî din ilan edip bütün kamusal kurumları ona göre düzenlemesi', 'Dinî törenlerin daha kalabalık yapılması'], 'Wilson sekülerleşmeyi, dinin toplumsal sistemin işleyişi üzerindeki etkisinin azalması olarak tanımladı.'),
  ('George Ritzer\'in büyük alışveriş merkezleri, eğlence parkları ve süper mağazalar gibi tüketimi büyüleyici kılan mekânlar için kullandığı kavram hangisidir?', 'Tüketimin katedralleri', ['Toplumun aynaları', 'Total kurumlar', 'Üçüncü mekânlar ve kahvehaneler'], 'Ritzer bu mekânların, bir zamanlar katedrallerin sağladığı büyülenme duygusunu tüketim için yeniden üreterek insanları daha çok harcamaya yönelttiğini savundu.'),
  ('Alan Bryman\'ın Disney eğlence parklarının ilkelerinin toplumun diğer alanlarına yayılmasını anlatmak için kullandığı kavram hangisidir?', 'Disneyleşme', ['McDonaldlaşma', 'Amerikanlaşma', 'Batılılaşma'], 'Bryman, tematik düzenleme, melez tüketim, ürün satışı ve duygusal emek gibi Disney parklarına özgü ilkelerin otellerden restoranlara pek çok alana yayıldığını gösterdi.'),
  ('Arlie Hochschild\'ın, bir cenazede üzgün, bir düğünde mutlu olmamız gerektiğini söyleyen toplumsal beklentileri anlatmak için kullandığı kavram hangisidir?', 'Duygu kuralları', ['Kolektif bilinç', 'Rol mesafesi', 'Sivil kayıtsızlık'], 'Hochschild\'a göre toplum yalnızca davranışlarımızı değil, belirli durumlarda neyi, ne kadar ve ne süreyle hissetmemiz gerektiğini de duygu kurallarıyla düzenler.'),
  ('George Gerbner\'in "ekme kuramı"na göre çok fazla televizyon izleyen kişilerde görülen etki hangisidir?', 'Dünyayı televizyondaki gibi tehlikeli algılama eğilimi', ['Okuma alışkanlığının ve kitap satın alma oranının kendiliğinden ve hızla artması', 'Siyasal görüşlerin hiç değişmemesi', 'Çevredeki insanlara güvenin artması'], 'Gerbner\'e göre uzun süreli televizyon izleme, izleyicinin gerçeklik algısını televizyon dünyasına benzetir; ağır izleyiciler suç ve şiddet riskini olduğundan büyük görür.'),
  ('Neil Postman\'ın "Televizyon: Öldüren Eğlence" adlı eserindeki temel kaygı hangisidir?', 'Kamusal söylemin eğlenceye dönüşüp ciddiyetini yitirmesi', ['Televizyonun yalnızca bilimsel bilgi yayması ve eğlence programlarının tümüyle ortadan kalkması', 'Kitapların tümüyle yasaklanması', 'Haberlerin çok uzun ve sıkıcı olması'], 'Postman, siyaset, eğitim ve din gibi alanların televizyon aracılığıyla eğlence mantığına uyarlandığını ve böylece akılcı kamusal tartışmanın zayıfladığını savundu.'),
  ('Bir hekimin ağır hastalığı olan bir hastaya duygularını belli etmeden, profesyonel ve soğukkanlı biçimde yaklaşması Parsons\'ın örüntü değişkenlerinden hangisini yansıtır?', 'Duygusal tarafsızlık', ['Duygusallık ve yakınlık', 'Yaygınlık', 'Özelcilik'], 'Parsons modern meslek rollerinin duygusal tarafsızlık gerektirdiğini; aile ilişkilerinin ise duygusallıkla nitelendiğini belirtir.'),
  ('Bir fast food zincirinin reklamlarında ürünün kalitesinden çok büyüklüğünü ve fiyatının düşüklüğünü öne çıkarması Ritzer\'in McDonaldlaşma boyutlarından hangisine örnektir?', 'Hesaplanabilirlik', ['Öngörülebilirlik ve tek tiplik', 'Verimlilik', 'Denetim'], 'Hesaplanabilirlik, niteliğin yerine sayılabilir niceliklerin, yani büyüklük, hız ve fiyatın ölçüt olarak öne çıkmasıdır.'),
  ('Bir restoranda çalışanların ne yapacağının ekrandaki talimatlar ve otomatik makinelerle belirlenmesi, böylece insan kararına yer bırakılmaması Ritzer\'in hangi boyutuna örnektir?', 'Teknolojiyle denetim', ['Hesaplanabilirlik ve nicelik', 'Öngörülebilirlik', 'Gösterişçi tüketim'], 'Ritzer\'e göre McDonaldlaşmış sistemlerde hem çalışanlar hem müşteriler, insan becerisinin yerini alan teknolojiler ve kurallarla giderek daha sıkı denetlenir.'),
  ('Yakalanan bir genç, "Asıl suçlu bizi sürekli taciz eden polislerdir, onlar bizden daha büyük hırsız" diyor. Bu ifade Sykes ve Matza\'nın hangi nötrleştirme tekniğine örnektir?', 'Suçlayanları suçlama', ['Zararın inkârı', 'Sorumluluğun inkârı tekniği', 'Kurbanın inkârı'], 'Suçlayanları suçlama tekniğinde birey, kendisini yargılayanların ikiyüzlü ya da yozlaşmış olduğunu öne sürerek dikkati kendi eyleminden uzaklaştırır.'),
  ('Üniversite bursu kazanmış bir gencin, gelecekteki kariyerini tehlikeye atmamak için arkadaşlarının yasa dışı bir eylemine katılmayı reddetmesi Hirschi\'nin hangi bağ öğesine örnektir?', 'Adanmışlık', ['Bağlanma', 'İnanç', 'Katılım'], 'Hirschi\'ye göre eğitim ve kariyere yaptığı yatırımlar nedeniyle kaybedecek çok şeyi olan kişi, bu yatırımı tehlikeye atacak suç davranışından kaçınır.'),
  ('Zygmunt Bauman\'ın "Akışkan Aşk" adlı eserinde çağdaş ilişkiler için kullandığı "bağlantı" benzetmesi neyi vurgular?', 'İlişkilerin kolayca kurulup koparılabilen geçici bağlara dönüşmesini', ['İlişkilerin ömür boyu sürecek biçimde güçlenmesini', 'Evliliklerin ve yakın ilişkilerin yalnızca aileler ve akrabalar tarafından düzenlenip denetlenmesini', 'İnsanların hiçbir ilişki kurmamasını'], 'Bauman, ağ çağında insanların bağlılık yükünden kaçınarak istedikleri an kopabilecekleri esnek bağlantıları tercih ettiğini ve bunun yalnızlık ile güvensizliği artırdığını savundu.'),
  ('Bir sosyolog, aynı mahalleye yeni taşınan iki ailenin birbirlerine yemek götürüp karşılığında yardım alarak ilişki kurmasını Mauss\'un çözümlemesine dayanarak açıklıyor. Bu açıklamanın kilit kavramı hangisidir?', 'Armağanın karşılık verme yükümlülüğü yaratması', ['Artı değerin el konulması', 'Kolektif coşku', 'Rasyonelleşme'], 'Mauss\'a göre armağan görünüşte gönüllü ama özünde verme, alma ve karşılık verme yükümlülükleri yaratan bir alışveriştir ve taraflar arasında kalıcı bağlar kurar.'),
  ('Aşağıdaki klasik sosyologlardan hangisi Alman\'dır?', 'Max Weber', ['Emile Durkheim', 'Auguste Comte', 'Herbert Spencer'], 'Max Weber Almanya\'da doğup çalıştı. Durkheim ve Comte Fransız, Spencer ise İngilizdir.'),
  ('"Kapital" adlı ünlü eserin yazarı kimdir?', 'Karl Marx', ['Adam Smith', 'Max Weber', 'John Maynard Keynes'], 'Kapital, Karl Marx\'ın kapitalist üretim tarzını çözümlediği başyapıtıdır; ilk cildi 1867\'de yayımlandı.'),
  ('Karl Marx\'ın en yakın çalışma arkadaşı olan ve birlikte birçok eser yazdığı düşünür kimdir?', 'Friedrich Engels', ['Georg Hegel', 'Ludwig Feuerbach', 'Max Weber'], 'Engels, Marx ile birlikte Komünist Parti Manifestosu ve Alman İdeolojisi\'ni yazdı, Marx\'ın ölümünden sonra da Kapital\'in kalan ciltlerini yayımladı.'),
  ('Türk sosyolojisinin kurucusu sayılan Ziya Gökalp hangi kentte doğmuştur?', 'Diyarbakır', ['Selanik', 'Konya', 'Erzurum'], 'Ziya Gökalp 1876\'da Diyarbakır\'da doğdu; ilk eğitimini burada aldıktan sonra İstanbul\'a gitti.'),
  ('İbn Haldun bugün hangi ülkenin sınırları içinde kalan bir kentte doğmuştur?', 'Tunus', ['Mısır', 'İspanya', 'Fas'], 'İbn Haldun 1332\'de Tunus\'ta doğdu; yaşamının sonlarını Kahire\'de geçirdi ve orada öldü.'),
  ('İbn Haldun\'un toplumsal düşüncelerini sistemli biçimde ortaya koyduğu en ünlü eseri hangisidir?', 'Mukaddime', ['Siyasetname', 'Kutadgu Bilig', 'Divanü Lügati\'t-Türk'], 'Mukaddime, İbn Haldun\'un toplum, devlet, ekonomi ve tarih yazımına ilişkin görüşlerini içeren eseridir; sosyolojinin öncü metinlerinden sayılır.'),
  ('Erving Goffman\'ın toplumsal etkileşimi tiyatro kavramlarıyla açıklayan yaklaşımına ne ad verilir?', 'Dramaturjik yaklaşım', ['Fenomenolojik yaklaşım', 'Yapısal işlevselci yaklaşım', 'Tarihsel materyalist yaklaşım'], 'Goffman bireyleri rol oynayan oyunculara, toplumsal ortamları sahneye benzettiği için yaklaşımı dramaturjik (tiyatrosal) yaklaşım olarak anılır.'),
  ('Yirminci yüzyılda ABD\'de yapısal işlevselciliğin en önemli kuramcısı sayılan sosyolog kimdir?', 'Talcott Parsons', ['C. Wright Mills', 'Herbert Blumer', 'Harold Garfinkel'], 'Parsons, toplumu birbiriyle ilişkili alt sistemlerden oluşan bir bütün olarak ele alan kapsamlı bir işlevselci kuram geliştirdi. Mills ise onun en sert eleştirmenlerindendir.'),
  ('Sosyolojideki çatışma kuramının düşünsel kökeninde en çok etkili olan klasik düşünür kimdir?', 'Karl Marx', ['Auguste Comte', 'Herbert Spencer', 'Charles Cooley'], 'Çatışma kuramı, toplumu çıkarları birbirine karşıt gruplar arasındaki mücadele üzerinden açıklayan Marx\'ın düşüncesinden büyük ölçüde beslenir.'),
  ('Sembolik etkileşimciliğin düşünsel öncüsü sayılan ve Chicago Üniversitesi\'nde felsefe dersleri veren düşünür kimdir?', 'George Herbert Mead', ['Talcott Parsons', 'Emile Durkheim', 'Karl Mannheim'], 'Mead\'in benlik, dil ve etkileşim üzerine görüşleri, öğrencisi Blumer tarafından sembolik etkileşimcilik adıyla sistemleştirildi.'),
  ('Frankfurt Okulu hangi ülkede kurulmuştur?', 'Almanya', ['Fransa', 'İngiltere', 'Avusturya'], 'Frankfurt Okulu adını Almanya\'nın Frankfurt kentinde kurulan Toplumsal Araştırmalar Enstitüsü\'nden alır.'),
  ('Aşağıdaki düşünürlerden hangisi postmodern kuramla ilişkilendirilir?', 'Jean-François Lyotard', ['Auguste Comte', 'Herbert Spencer', 'Emile Durkheim'], 'Lyotard "Postmodern Durum" adlı eseriyle postmodern düşüncenin önde gelen isimlerinden biridir. Diğerleri sosyolojinin klasik dönem düşünürleridir.'),
  ('Aşağıdaki kuramsal yaklaşımlardan hangisi toplumu bütün olarak ele alan makro düzeyde bir yaklaşımdır?', 'Yapısal işlevselcilik', ['Sembolik etkileşimcilik', 'Etnometodoloji', 'Dramaturjik yaklaşım'], 'Yapısal işlevselcilik toplumu kurumlar ve sistemler düzeyinde inceler. Diğer üç yaklaşım yüz yüze etkileşimi inceleyen mikro yaklaşımlardır.'),
  ('Sosyologları doğdukları ve çalıştıkları ülkelerle eşleştiren bir öğrencinin hangi eşleştirmesi doğrudur?', 'Pierre Bourdieu - Fransa', ['Max Weber - İngiltere', 'Herbert Spencer - Almanya', 'Talcott Parsons - Fransa'], 'Bourdieu Fransız sosyologdur. Weber Alman, Spencer İngiliz, Parsons ise Amerikalıdır.'),
  ('Chicago Okulu sosyologlarının kenti bir "toplumsal laboratuvar" olarak görmesi onları hangi araştırma tarzına yöneltmiştir?', 'Kentin mahallelerinde yürütülen alan araştırmalarına', ['Yalnızca kütüphanede kuramsal çalışmaya', 'Yalnızca hayvan deneylerine', 'Yalnızca matematiksel modellere'], 'Chicago Okulu sosyologları göçmen mahalleleri, çeteler ve evsizler gibi konuları doğrudan gözlem, görüşme ve kişisel belgelerle sahada incelediler.'),
  ('Aşağıdaki sosyologlardan hangisi sosyolojinin klasik kurucuları arasında sayılan üç büyük isimden biri değildir?', 'Pierre Bourdieu', ['Karl Marx', 'Emile Durkheim', 'Max Weber'], 'Marx, Durkheim ve Weber genellikle sosyolojinin üç klasik kurucusu olarak anılır. Bourdieu 20. yüzyılın ikinci yarısında öne çıkan çağdaş bir sosyologdur.'),
  ('Bir sosyolog, toplumsal olayları açıklarken insanların birbirlerinin davranışlarına yükledikleri anlamlara ve yorumlara odaklanıyor. Bu sosyolog en çok hangi yaklaşımı benimsemiştir?', 'Yorumlayıcı (anlamacı) yaklaşım', ['Pozitivist yaklaşım', 'Tarihsel materyalist yaklaşım', 'Sosyal Darwinist yaklaşım'], 'Weber\'den sembolik etkileşimciliğe uzanan yorumlayıcı gelenek, toplumsal eylemin aktörler için taşıdığı anlamı kavramayı amaçlar.'),
  ('Aşağıdaki kavramlardan hangisi Karl Marx\'ın kuramıyla ilişkili değildir?', 'Kolektif coşku', ['Artı değer', 'Sınıf bilinci', 'Üretim ilişkileri'], 'Kolektif coşku Durkheim\'ın din sosyolojisindeki kavramıdır. Artı değer, sınıf bilinci ve üretim ilişkileri Marx\'ın temel kavramlarıdır.'),
  ('Aşağıdaki kavramlardan hangisi Emile Durkheim\'ın kuramına aittir?', 'Organik dayanışma', ['İdeal tip', 'Sınıf bilinci', 'Ön sahne'], 'Organik dayanışma Durkheim\'ın kavramıdır. İdeal tip Weber\'e, sınıf bilinci Marx\'a, ön sahne ise Goffman\'a aittir.'),
  ('"Sosyoloji" terimi ilk kez hangi ülkede ortaya atılmıştır?', 'Fransa', ['Almanya', 'İngiltere', 'İtalya'], 'Terim Fransız düşünür Auguste Comte tarafından 19. yüzyılın ilk yarısında Pozitif Felsefe Dersleri\'nde kullanıldı.'),
  ('Karl Marx hangi ülkede doğmuştur?', 'Almanya', ['Fransa', 'İngiltere', 'Rusya'], 'Marx 1818\'de bugünkü Almanya\'nın Trier kentinde doğdu; sürgün yıllarının ardından ömrünün son otuz yılından fazlasını Londra\'da geçirdi.'),
  ('Aşağıdaki düşünürlerden hangisi 20. yüzyılı görmeden ölmüştür?', 'Auguste Comte', ['Max Weber', 'Emile Durkheim', 'Georg Simmel'], 'Comte 1857\'de öldü. Durkheim 1917\'de, Simmel 1918\'de, Weber ise 1920\'de öldü.'),
  ('Marx, Durkheim ve Weber\'den hangisi en önce doğmuştur?', 'Karl Marx', ['Emile Durkheim', 'Max Weber', 'Üçü de aynı yıl doğmuştur'], 'Marx 1818\'de, Durkheim 1858\'de, Weber ise 1864\'te doğdu; Marx klasik kurucuların en eski kuşağındandır.'),
  ('İktisatta kendi adıyla anılan "optimum" kavramıyla da tanınan ve seçkinler kuramıyla sosyolojiye katkıda bulunan İtalyan düşünür kimdir?', 'Vilfredo Pareto', ['Gaetano Mosca', 'Antonio Gramsci', 'Robert Michels'], 'Pareto hem iktisatçı hem sosyologdur; iktisattaki Pareto optimumu kavramı ve sosyolojideki seçkinlerin dolaşımı kuramı onun adıyla anılır.'),
  ('Ziya Gökalp hangi dönemde yaşamıştır?', 'Osmanlı\'nın son dönemi ile Cumhuriyet\'in ilk yıllarında', ['Tanzimat Fermanı\'nın ilanından önce', 'İkinci Dünya Savaşı\'ndan sonra', 'Kanuni Sultan Süleyman döneminde'], 'Gökalp 1876\'da doğdu ve 1924\'te öldü; II. Meşrutiyet, Birinci Dünya Savaşı ve Millî Mücadele dönemlerinde etkin oldu.'),
  ('Aşağıdakilerden hangisi Frankfurt Okulu\'nun üyeleri arasında yer almaz?', 'Talcott Parsons', ['Theodor Adorno', 'Max Horkheimer', 'Herbert Marcuse'], 'Parsons Amerikalı bir yapısal işlevselcidir. Adorno, Horkheimer ve Marcuse ise Frankfurt Okulu\'nun önde gelen isimleridir.'),
  ('Aşağıdaki sosyologlardan hangisi Chicago Okulu ile ilişkilendirilmez?', 'Theodor Adorno', ['Robert Park', 'Ernest Burgess', 'Louis Wirth'], 'Park, Burgess ve Wirth Chicago Okulu\'nun kent sosyolojisi çalışmalarının önde gelen isimleridir. Adorno Frankfurt Okulu\'na mensuptur.'),
  ('Bir girişimcinin sahip olduğu fabrika, banka hesabı ve gayrimenkuller Bourdieu\'nün sermaye türlerinden hangisine girer?', 'Ekonomik sermaye', ['Kültürel sermaye', 'Toplumsal sermaye', 'Sembolik sermaye'], 'Bourdieu\'ye göre doğrudan paraya çevrilebilen mülk ve gelir ekonomik sermayedir; eğitim ve beğeni kültürel, ilişki ağları toplumsal, saygınlık ise sembolik sermayedir.'),
  ('Aşağıdaki kavramlardan hangisi Erving Goffman\'a ait değildir?', 'Artı değer', ['Damga', 'Total kurum', 'Rol mesafesi'], 'Artı değer Marx\'ın kavramıdır. Damga, total kurum ve rol mesafesi Goffman\'ın çalışmalarında geliştirdiği kavramlardır.'),
  ('Bourdieu\'nün sosyolojisini anlatan bir sunumda yer almaması gereken, başka bir düşünüre ait kavram hangisidir?', 'Genelleştirilmiş öteki', ['Habitus', 'Kültürel sermaye', 'Sembolik şiddet'], 'Genelleştirilmiş öteki George Herbert Mead\'in kavramıdır. Habitus, kültürel sermaye ve sembolik şiddet Bourdieu\'nün temel kavramlarıdır.'),
  ('Aşağıdaki kavramlardan hangisi Georg Simmel ile ilişkilidir?', 'Yabancı', ['Demir kafes', 'Habitus', 'Hipergerçeklik'], 'Simmel\'in "Yabancı" adlı denemesi sosyolojinin klasik metinlerindendir. Demir kafes Weber\'e, habitus Bourdieu\'ye, hipergerçeklik Baudrillard\'a aittir.'),
  ('Kavramları sahipleriyle eşleştiren bir listede yalnızca bir satır doğrudur. Doğru satır hangisidir?', 'Yaşam dünyası - Jürgen Habermas', ['Asabiyet - Auguste Comte', 'Akışkan modernlik - Max Weber', 'Kültürel sermaye - Karl Marx'], 'Yaşam dünyası Habermas\'ın kavramıdır. Asabiyet İbn Haldun\'a, akışkan modernlik Bauman\'a, kültürel sermaye Bourdieu\'ye aittir.'),
  ('Ders notlarında kuramcılara mal edilen kavramlardan biri yanlış kişiye yazılmıştır. Yanlış yazılan satır hangisidir?', 'Yapılaşma kuramı - Emile Durkheim', ['Risk toplumu - Ulrich Beck', 'Ağ toplumu - Manuel Castells', 'Seçkinlerin dolaşımı - Vilfredo Pareto'], 'Yapılaşma (strüktürasyon) kuramı Anthony Giddens\'a aittir. Diğer eşleştirmeler doğrudur.'),
  ('Bir sosyolog, insanların toplumsal statülerini göstermek için pahalı markalı ürünler satın almasını inceliyor. Bu araştırma için en uygun kuramsal kaynak hangi sosyoloğun çalışmalarıdır?', 'Thorstein Veblen', ['George Herbert Mead', 'Harold Garfinkel', 'Robert Park'], 'Veblen\'in gösterişçi tüketim çözümlemesi, malların statü göstermek için tüketilmesini açıklamada temel kaynaktır.'),
  ('Bir araştırmacı, cezaevlerinde mahkûmların gün boyu nasıl gözetlendiğini ve zaman çizelgeleriyle nasıl düzenlendiğini incelemek istiyor. Bu araştırma için en uygun kuramsal kaynak hangisidir?', 'Michel Foucault\'nun disiplin çözümlemesi', ['Comte\'un üç hal yasası', 'Tönnies\'in cemaat-cemiyet ayrımı', 'Spencer\'ın evrim kuramı'], 'Foucault "Hapishanenin Doğuşu"nda gözetim, zaman çizelgeleri ve beden disiplini üzerinden işleyen modern iktidarı inceledi.'),
  ('Marx\'ın kuramında "burjuvazi" hangi toplumsal kesimi anlatır?', 'Üretim araçlarına sahip olan kapitalist sınıfı', ['Toprağa bağlı çalışan serfleri', 'Emek gücünü satarak geçinen işçileri', 'Dilencileri ve serserileri'], 'Marx\'a göre burjuvazi fabrikalar, makineler ve sermaye gibi üretim araçlarının sahibi olan ve işçi çalıştıran sınıftır.'),
  ('Marx\'ın kuramında "proletarya" hangi kesimi anlatır?', 'Üretim araçlarına sahip olmayıp emek gücünü satarak geçinen işçi sınıfını', ['Fabrika ve toprak sahiplerini', 'Yalnızca devlet memurlarını', 'Kilise mensuplarını'], 'Proletarya, geçimini ücret karşılığında emek gücünü satarak sağlayan ve üretim araçları üzerinde mülkiyeti olmayan modern işçi sınıfıdır.'),
  ('Merton\'un uyum biçimleri tipolojisinde toplumun hem kabul ettiği amaçları hem de bu amaçlara ulaşmak için öngördüğü yasal araçları benimseyen bireyin uyum biçimi hangisidir?', 'Uyma', ['Yenilikçilik', 'Başkaldırı', 'Geri çekilme'], 'Merton\'a göre toplumların çoğunluğu, kültürel amaçları da kurumsal araçları da kabul eden uyma biçimini gösterir; toplumsal düzenin sürmesini sağlayan budur.'),
  ('Weber\'in yönteminde kullanılan Almanca "Verstehen" sözcüğünün Türkçe karşılığı hangisidir?', 'Anlama', ['Açıklama', 'Ölçme', 'Sınıflama'], 'Verstehen "anlama" demektir; Weber\'in toplumsal eylemi eylemcinin öznel anlamı üzerinden kavrama yöntemini anlatır.'),
  ('"Sosyal Darwinizm" adını hangi doğa bilimcinin kuramından almıştır?', 'Charles Darwin', ['Gregor Mendel', 'Isaac Newton', 'Louis Pasteur'], 'Sosyal Darwinizm, Darwin\'in doğal seçilim kuramını toplumlara ve sınıflara uyarlayan görüşlere verilen addır; Spencer bu düşüncenin en etkili temsilcisidir.'),
  ('Weber\'in ünlü "demir kafes" benzetmesi hangi eserinin son sayfalarında yer alır?', 'Protestan Ahlakı ve Kapitalizmin Ruhu', ['Ekonomi ve Toplum', 'Hindistan\'ın Dini', 'Bilim Meslek Olarak'], 'Weber Protestan Ahlakı\'nın sonunda, dinsel ruhu kaybolmuş modern kapitalist düzenin bireyleri kuşatan bir "demir kafes"e dönüştüğünü yazar.'),
  ('Habermas\'a göre "iletişimsel eylem"in temel amacı hangisidir?', 'Taraflar arasında karşılıklı anlaşmaya ve uzlaşmaya varmak', ['Karşıdakini zorla kendi çıkarına hizmet ettirmek', 'Yalnızca ekonomik kâr elde etmek', 'Karşıdakini aldatarak başarı kazanmak'], 'Habermas, başarıya yönelik stratejik eylemden farklı olarak iletişimsel eylemin dil aracılığıyla ortak bir anlayışa ulaşmayı hedeflediğini vurgular.'),
  ('Zygmunt Bauman\'ın "akışkan modernlik" kavramının karşısına koyduğu, kalıcı kurumlar ve uzun vadeli bağlılıklarla nitelenen önceki modernlik evresine verdiği ad hangisidir?', 'Katı modernlik', ['Erken antikçağ', 'Feodal modernlik', 'Dinsel modernlik'], 'Bauman, fabrikaların, ömür boyu işlerin ve sağlam kurumların egemen olduğu dönemi katı modernlik; her şeyin geçici ve esnekleştiği günümüzü ise akışkan modernlik olarak adlandırır.'),
  ('Mübeccel Kıray\'ın monografisine konu olan Ereğli hangi bölgemizde yer alır?', 'Karadeniz Bölgesi', ['Ege Bölgesi', 'Doğu Anadolu Bölgesi', 'Akdeniz Bölgesi'], 'Kıray, Zonguldak iline bağlı Karadeniz kıyısındaki Ereğli\'yi demir-çelik fabrikası kurulmadan önce inceleyerek sanayileşmenin toplumsal etkilerini öngörmeye çalıştı.'),
  ('Durkheim\'a göre bir toplumda suç oranının olağan düzeyin çok üstüne çıkması nasıl değerlendirilmelidir?', 'Patolojik bir durumun belirtisi olarak', ['Normal ve sağlıklı bir durum olarak', 'Toplumun ahlaki olarak ilerlediğinin kanıtı olarak', 'Sosyolojinin ilgi alanı dışında bir olay olarak'], 'Durkheim belirli ölçüde suçun normal olduğunu kabul eder; ancak suç oranının o toplum tipinin ortalamasını çok aşması toplumsal bir bozukluğun, yani patolojinin göstergesidir.'),
  ('Comte\'a göre toplumsal dinamiğin, yani toplumsal değişmenin temel yasası hangisidir?', 'Üç hal yasası', ['Arz ve talep yasası', 'Seçkinlerin dolaşımı', 'Oligarşinin tunç yasası'], 'Comte toplumsal dinamiği insan zihninin teolojik, metafizik ve pozitif aşamalardan geçişini anlatan üç hal yasasıyla açıkladı.'),
  ('Weber\'in bürokrasi ideal tipine göre memurlar nasıl ücretlendirilir?', 'Makamın gerektirdiği sabit bir maaşla', ['Yalnızca halktan topladıkları bağışlarla', 'Yönettikleri toprağın ürününden pay alarak', 'Hiçbir ücret almadan gönüllü olarak'], 'Weber\'e göre bürokratik memur, makamın sahibi değildir; kariyer basamaklarına bağlı düzenli ve sabit bir maaş alır.'),
  ('Bir sosyolog, işyerindeki yöneticilerin emir verme yetkisinin çalışanlarla sürekli bir çıkar çatışması doğurduğunu ileri sürüyor. Bu görüş en çok hangi sosyoloğun kuramına yakındır?', 'Ralf Dahrendorf', ['Talcott Parsons', 'George Herbert Mead', 'Auguste Comte'], 'Dahrendorf, modern örgütlerde otorite sahipleri ile otoriteye tabi olanlar arasındaki ilişkinin çatışmanın temel kaynağı olduğunu savundu.'),
  ('Bir sosyolog, gençlerin internetteki profillerinde kendilerini en çekici biçimde sunmak için fotoğraflarını özenle seçmesini inceliyor. Bu araştırmada en çok yararlanılabilecek sosyolog kimdir?', 'Erving Goffman', ['Karl Marx', 'Auguste Comte', 'Immanuel Wallerstein'], 'Goffman\'ın benliğin sunumu ve izlenim yönetimi üzerine çözümlemeleri, kişilerin başkalarının gözünde belirli bir imaj yaratma çabalarını incelemek için temel bir çerçeve sunar.'),
  ('Bir sosyolog, dünya ekonomisinde zengin merkez ülkelerin yoksul çevre ülkelerin hammaddesini ucuza alıp işlenmiş ürün satmasını eşitsizliğin kaynağı olarak görüyor. Bu görüş hangi kuramsal geleneğe yakındır?', 'Dünya sistemleri ve bağımlılık yaklaşımlarına', ['Sembolik etkileşimciliğe', 'Etnometodolojiye', 'Dramaturjik yaklaşıma'], 'Merkez-çevre arasındaki eşitsiz değişimi vurgulamak, Wallerstein\'ın dünya sistemleri kuramının ve bağımlılık okulunun ortak noktasıdır.'),
];
